{"q": 20892, "quiz": 1797, "obj": "P3.MAIN_PARA", "kind": "mcq", "was": "sentence", "body": "Read the short poem near the end. What is its big idea?", "why": "فكرة المقطع في سطره الأخير: «Conserve water, so it’ll stay!»", "opts": [{"t": "Look for new water under every town.", "dx": "MIX", "key": false}, {"t": "Swim in every river and in every bay.", "dx": "ECHO", "key": false}, {"t": "Say bye to water, and it can come back.", "dx": "REV", "key": false}, {"t": "Save water, and it can stay with us.", "dx": null, "key": true}]},
{"q": 20893, "quiz": 1797, "obj": "P3.CHANGE", "kind": "mcq", "was": "sentence", "body": "On the first evening, the town was sad. How was it different the next morning?", "why": "التغيّر بين المساء والصباح وما أحدثه: «gloom descended on the town» ثم «people were cheering and celebrating» لأن «Water is back!»", "opts": [{"t": "People were angry, because the drill broke.", "dx": "JUMP", "key": false}, {"t": "People were tired, because they were hungry.", "dx": "MIX", "key": false}, {"t": "People were happy, because water was back.", "dx": null, "key": true}, {"t": "People were afraid, because Earth was hot.", "dx": "MIX", "key": false}]},
{"q": 20894, "quiz": 1797, "obj": "P4.CONSEQUENCE", "kind": "relabel"},
{"q": 20895, "quiz": 1798, "obj": "P1.PARAPHRASE", "kind": "mcq", "was": "sentence", "body": "What did Dad show Tara on the bad bread?", "why": "السؤال يعيد صياغة قول الأب: «do you see the green spots on the bread? That's mould and it is growing on the bread.»", "opts": [{"t": "Green spots of mould.", "dx": null, "key": true}, {"t": "Brown spots of butter.", "dx": "JUMP", "key": false}, {"t": "Yellow spots of egg.", "dx": "MIX", "key": false}, {"t": "White spots of milk.", "dx": "MIX", "key": false}]},
{"q": 20896, "quiz": 1798, "obj": "P2.UNSIGNALLED", "kind": "mcq", "was": "sentence", "body": "Why was the food in the fridge bad?", "why": "السبب بلا أداة ربط: «Dad mentioned that the fridge has been broken for quite a while.» ثم «There is no cold air».", "opts": [{"t": "The fridge had too much food.", "dx": "GAP", "key": false}, {"t": "The fridge had an open door.", "dx": "GAP", "key": false}, {"t": "The fridge had no cold air.", "dx": null, "key": true}, {"t": "The fridge had a monster in it.", "dx": "LITR", "key": false}]},
{"q": 20897, "quiz": 1798, "obj": "P2.WORD_CONTEXT", "kind": "mcq", "was": "sentence", "body": "What does the word \"refrigerated\" mean in this book?", "why": "المعنى من الجملة نفسها وما حولها: «Milk needs to be refrigerated to stay fresh» و«The cool air from the fridge helps to keep the food fresh for a longer time.»", "opts": [{"t": "Put in a hot room.", "dx": "REV", "key": false}, {"t": "Put in a cold place.", "dx": null, "key": true}, {"t": "Put on the floor.", "dx": "MIX", "key": false}, {"t": "Put in a trash bag.", "dx": "MIX", "key": false}]},
{"q": 20898, "quiz": 1798, "obj": "P3.MAIN_PARA", "kind": "mcq", "was": "sentence", "body": "Read the last lines of the book, about foods. What is the big idea there?", "why": "فكرة الفقرة في جملتها الأولى: «Some foods go bad faster than others, and some go bad very slowly.»", "opts": [{"t": "Fruits and vegetables are the best foods.", "dx": "JUMP", "key": false}, {"t": "Some foods spoil fast, and some spoil slowly.", "dx": null, "key": true}, {"t": "Eggs and meat are bad for small children.", "dx": "ECHO", "key": false}, {"t": "All foods spoil at the same time in a house.", "dx": "REV", "key": false}]},
{"q": 20899, "quiz": 1798, "obj": "P1.COMPETITOR", "kind": "mcq", "was": "sentence", "body": "What foods spoil the slowest?", "why": "جملتان تتنافسان: «Pickled foods like kimchi and ghee go bad very slowly.» لكن المطلوب الأبطأ: «Packaged foods, like cookies and candy, are the slowest to spoil.»", "opts": [{"t": "Dried foods, like rice.", "dx": "MIX", "key": false}, {"t": "Wet foods, like fruits.", "dx": "REV", "key": false}, {"t": "Packaged foods, like candy.", "dx": null, "key": true}, {"t": "Pickled foods, like kimchi.", "dx": "MIX", "key": false}]},
{"q": 20900, "quiz": 1798, "obj": "P4.FIT", "kind": "mcq", "was": "judge", "body": "The words \"Invisible monster\" are at the top of one page. Is this a good name for that page?", "why": "العنوان يفي بما تحته: «there were unseen things in the house» و«something we cannot see is eating it».", "opts": [{"t": "No. The page tells only about fried rice for dinner.", "dx": "MIX", "key": false}, {"t": "No. The page tells only about a clean, cold fridge.", "dx": "MIX", "key": false}, {"t": "Yes. The page tells about tiny unseen things in the house.", "dx": null, "key": true}, {"t": "Yes. The page tells about a big monster under the bed.", "dx": "LITR", "key": false}]},
{"q": 22835, "quiz": 2124, "obj": "P1.PARAPHRASE", "kind": "mcq", "was": "sentence", "body": "What does the lab do with Mukhil's blood?", "why": "السؤال يعيد صياغة قول الطبيب: «The lab will check your blood to see if everything is alright.»", "opts": [{"t": "Use it for a sick child at school.", "dx": "GAP", "key": false}, {"t": "Look at it to see if all is well.", "dx": null, "key": true}, {"t": "Put it back into her left arm.", "dx": "JUMP", "key": false}, {"t": "Keep it cold for the next year.", "dx": "GAP", "key": false}]},
{"q": 22836, "quiz": 2124, "obj": "P2.MOTIVE", "kind": "mcq", "was": "sentence", "body": "Amma tells Mukhil about the three litres of blood in a child's body. Why?", "why": "الدافع من خوف موخيل وجواب أمها في الفقرة نفسها: «But what if all my blood drips out and I end up empty?» ثم «The doctor will just need a few drops.»", "opts": [{"t": "The doctor wants three litres for the test.", "dx": "REV", "key": false}, {"t": "Mukhil has a maths test about litres.", "dx": "MIX", "key": false}, {"t": "Mukhil is afraid for all the blood in her body.", "dx": null, "key": true}, {"t": "Mukhil wants to learn about blood for school.", "dx": "JUMP", "key": false}]},
{"q": 22837, "quiz": 2124, "obj": "P2.WORD_CONTEXT", "kind": "mcq", "was": "sentence", "body": "What is a \"tourniquet\" in this story?", "why": "المعنى من السياق القريب: «Mukhil sees a nurse coming towards her with a long rubber cord.» ثم يقول الطبيب «This is a tourniquet.»", "opts": [{"t": "A long white coat.", "dx": "MIX", "key": false}, {"t": "A long rubber cord.", "dx": null, "key": true}, {"t": "A small piece of cotton.", "dx": "MIX", "key": false}, {"t": "A small plastic tube.", "dx": "MIX", "key": false}]},
{"q": 22838, "quiz": 2124, "obj": "P3.CHANGE", "kind": "mcq", "was": "sentence", "body": "How does Mukhil's feeling about the blood test change in the story?", "why": "التغيّر بين أول القصة وآخرها: في البداية «She is terrified.» وفي الخاتمة «she can't WAIT to tell her friends at school about how she passed her first blood test!»", "opts": [{"t": "First she likes the clinic. In the end she hates it.", "dx": "REV", "key": false}, {"t": "First she is angry with Amma. In the end she says sorry.", "dx": "JUMP", "key": false}, {"t": "First she is afraid of it. In the end she is happy about it.", "dx": null, "key": true}, {"t": "First she is happy about it. In the end she is afraid of it.", "dx": "REV", "key": false}]},
{"q": 22839, "quiz": 2124, "obj": "P4.WORD_CHOICE", "kind": "mcq", "was": "sentence", "body": "At the end, Mukhil uses the word \"passed\" for her blood test. Why does the writer use this word?", "why": "اختيار الكلمة يعيدنا إلى خلطها الأول بين الفحص والامتحان: «But I have not studied for any tests!» ثم «Have I passed?»", "opts": [{"t": "Mukhil passed her maths test that morning.", "dx": "MIX", "key": false}, {"t": "The doctor passed by her house that day.", "dx": "ECHO", "key": false}, {"t": "The fever passed in the night at home.", "dx": "ECHO", "key": false}, {"t": "Mukhil still thinks of it like a school test.", "dx": null, "key": true}]},
{"q": 22840, "quiz": 2124, "obj": "P4.REASON_SUPPORTS", "kind": "mcq", "was": "judge", "body": "Mukhil jumps out of the chair at the clinic. Is she brave after that?", "why": "بعد قول الأم «You will need to be brave,» يأتي الفعل: «So Mukhil climbs back in and shuts her eyes.»", "opts": [{"t": "No. She yells until Amma takes her home.", "dx": "REV", "key": false}, {"t": "Yes. She smiles at the needle and helps the nurse.", "dx": "JUMP", "key": false}, {"t": "Yes. She climbs back into the chair and shuts her eyes.", "dx": null, "key": true}, {"t": "No. She leaves the clinic before the test.", "dx": "REV", "key": false}]}
]$spec$::jsonb;
  e jsonb; o jsonb; r record;
  v_q bigint; v_obj bigint; v_id bigint; v_key bigint; v_dx jsonb; i int; n int;
  n_done int := 0; n_skip int := 0;
begin
  /* ── الحرّاس: كلُّ سؤالٍ في اختباره، من مكتبة المادّة ٧، وما يتحوّل بلا إجابة ── */
  for r in select (x->>'q')::bigint q, (x->>'quiz')::bigint quiz from jsonb_array_elements(spec) x loop
    if not exists (select 1 from questions qq join items it on it.quiz_id = qq.quiz_id join lessons l on l.id = it.lesson_id
                    join courses c on c.id = l.course_id
                    where qq.id = r.q and qq.quiz_id = r.quiz and c.subject_id = 7 and qq.retired_at is null) then
      raise exception 'السؤال % ليس في الاختبار % من مكتبة المادّة ٧', r.q, r.quiz;
    end if;
  end loop;
  select count(*) into n from answers a
   where a.question_id in (select (x->>'q')::bigint from jsonb_array_elements(spec) x where x->>'kind' <> 'relabel');
  if n > 0 then raise exception 'على الأسئلة % إجابة — لا يُحوَّل سؤالٌ أجاب عنه أحد', n; end if;

  for e in select * from jsonb_array_elements(spec) loop
    v_q := (e->>'q')::bigint;
    select kind, body, objective_id into r from questions where id = v_q;
    select id into strict v_obj from objectives where subject_id = 7 and code = e->>'obj';

    if e->>'kind' = 'relabel' then
      if r.objective_id is distinct from v_obj then update questions set objective_id = v_obj where id = v_q; n_done := n_done + 1;
      else n_skip := n_skip + 1; end if;
      continue;
    end if;

    if r.kind = e->>'kind' and r.body = e->>'body' then n_skip := n_skip + 1; continue; end if;
    if r.kind <> e->>'was' then raise exception 'السؤال % نمطُه % لا %', v_q, r.kind, e->>'was'; end if;

    update question_keys set correct_id = null, correct_ids = null where question_id = v_q;
    delete from options where question_id = v_q;

    if e->>'kind' = 'mcq' then
      v_key := null; v_dx := '{}'::jsonb; i := 0;
      for o in select * from jsonb_array_elements(e->'opts') loop
        i := i + 1;
        insert into options (question_id, position, body) values (v_q, i, o->>'t') returning id into v_id;
        if (o->>'key')::boolean then v_key := v_id;
        elsif o->>'dx' is not null then v_dx := v_dx || jsonb_build_object(v_id::text, o->>'dx'); end if;
      end loop;
      if v_key is null then raise exception 'السؤال % بلا مفتاح', v_q; end if;
      update questions set kind = 'mcq', body = e->>'body', objective_id = v_obj where id = v_q;
      update question_keys set correct_id = v_key, correct_ids = null, accept = null, bank = null, wrong_map = null,
             dx_map = v_dx, explanation = e->>'why' where question_id = v_q;
    else   -- matching
      i := 0;
      for o in select * from jsonb_array_elements(e->'prompts') loop
        i := i + 1;
        insert into options (question_id, position, body, item_key) values (v_q, i, o->>'t', o->>'k');
      end loop;
      update questions set kind = 'matching', body = e->>'body', objective_id = v_obj, points = i where id = v_q;
      update question_keys set correct_id = null, correct_ids = null, wrong_map = null, dx_map = '{}'::jsonb,
             bank = e->'bank', accept = jsonb_build_object('pairs', e->'pairs'), explanation = e->>'why' where question_id = v_q;
    end if;
    get diagnostics n = row_count;
    if n <> 1 then raise exception 'السؤال % بلا سطر مفتاح', v_q; end if;
    n_done := n_done + 1;
  end loop;

  if n_done + n_skip <> 48 then raise exception 'عُدِّل % وتُخطّي % والمنتظر 48', n_done, n_skip; end if;
  raise notice '254: عُدِّل % سؤالاً · تُخطّي %', n_done, n_skip;
end $$;

insert into public.sql_log (n, title, applied_at)
values ('254', 'أسئلةُ كتب R10 في مكتبة بيان (٢ من ٣) — «الضغط على الجملة» و«حكمٌ ودليلُه» يصيران اختياراً من متعدّد', now())
on conflict (n) do update set applied_at = now();
